/**
 * Create diagram optionally pass the JSON model to load and onChange handler.
 *
 * @param {string} containerElemntId Id of the element used as diagram container.
 * @param {string} [jsonModel] JSON representation of the model (containing semantic and diagram parts).
 *       If model is 'undefined' or 'null' new then initial diagram model will be created.
 * @param {function(context)} [onChange] Callback to be called when a diagram change occurs.
 *        The 'context' object contains:
 *        - 'event' - on change event containing modified elements.
 *        - 'diagram' - diagram reference. (Use: diagram.getModelJson([format]) - to getserialized json.)
 * @param [that] object to be use as 'this' for onChange.
 * @param {object} [options] Additional options for diagram. Currently {readOnly: true | false - default}.
 *
 * @returns {DtDiagram} diagram.
 */
function createDiagram(containerElemntId, jsonModel, onChange, that, options) {
  // containerElemntId is type is string use getElementById to get the element or else use it directly as container.
  var container = typeof containerElemntId === 'string' ? document.getElementById(containerElemntId) : containerElemntId;
  var DtDiagram = _DtDiagram__WEBPACK_IMPORTED_MODULE_3__["default"];
  var diagram = new DtDiagram({
    container: container,
    width: '100%',
    height: '100%',
    position: 'relative'
  });
  function cb(err, warnings) {
    if (err) {
      console.log('Errors: ' + err);
    }
    if (warnings) {
      console.log('Warnings: ' + warnings);
    }
  }
  diagram.createDiagram(jsonModel, cb, onChange, that, options);
  return diagram;
}

